"use client";

import type React from "react";
import { BRAND } from "@/lib/brand";

interface TriCircleMarkV2Props {
  size?: number;
  className?: string;
  style?: React.CSSProperties;
}

export function TriCircleMarkV2({ size = 40, className, style }: TriCircleMarkV2Props) {
  const r = size / 2;
  const offset = size * 0.22;

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      style={style}
      aria-label="InkOS mark"
    >
      {/* Bottom-left circle — rust */}
      <circle
        cx={r - offset}
        cy={r + offset * 0.6}
        r={r * 0.52}
        fill={BRAND.rust}
        opacity={0.9}
      />
      {/* Bottom-right circle — onyx */}
      <circle
        cx={r + offset}
        cy={r + offset * 0.6}
        r={r * 0.52}
        fill={BRAND.onyx}
        opacity={0.85}
      />
      {/* Top circle — amber */}
      <circle
        cx={r}
        cy={r - offset * 0.85}
        r={r * 0.52}
        fill={BRAND.amber}
        opacity={0.75}
      />
    </svg>
  );
}

