                transition: "background 0.15s",
              } as React.CSSProperties}
            >
              Start free
            </a>

            {/* Mobile burger */}
            <button
              className="inkos-nav-burger"
              onClick={() => setOpen((v) => !v)}
              style={{
                display: "none",
