                  </div>
                  <div style={{
                    fontFamily: FONT.sans,
                    fontSize: 20,
                    fontWeight: 600,
                    color: BRAND.ink,
                    letterSpacing: "-0.02em",
                    lineHeight: 1,
                    marginBottom: 4,
                  } as React.CSSProperties}>{kpi.value}</div>
                  <div style={{
                    fontFamily: FONT.sans,
                    fontSize: 10,
                    color: kpi.up ? BRAND.sage : BRAND.rust,
                    fontWeight: 500,
                  } as React.CSSProperties}>{kpi.change} vs last week</div>
                </div>
              );
            })}
          </div>

          {/* Allergy alert */}
          <div style={{
            background: BRAND.amberWash,
            border: `1px solid ${BRAND.amberSoft}`,
            borderRadius: 10,
            padding: "10px 14px",
            display: "flex",
            alignItems: "center",
            gap: 10,
          } as React.CSSProperties}>
            <AlertTriangle size={14} strokeWidth={2} style={{ color: BRAND.amber, flexShrink: 0 } as React.CSSProperties} />
            <div>
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                fontWeight: 600,
                color: BRAND.ink,
              } as React.CSSProperties}>Allergy alert — Elena Ruiz </span>
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                color: BRAND.stoneDark,
              } as React.CSSProperties}>Known sensitivity to red ink (Eternal Ink Crimson Red). Patch tested 2024-11. Use black or sage alternatives for fill.</span>
            </div>
          </div>

          {/* Bottom grid: schedule + project pulse */}
          <div style={{
            display: "grid",
            gridTemplateColumns: "1fr 280px",
            gap: 14,
            flex: 1,
          } as React.CSSProperties}>

            {/* Schedule */}
            <div style={{
              background: BRAND.white,
              border: `1px solid ${BRAND.border}`,
              borderRadius: 10,
              padding: "14px",
            } as React.CSSProperties}>
              <DashSectionHeader label="Today's schedule" action="View full calendar" />
              {/* Column headers */}
              <div style={{
                display: "grid",
                gridTemplateColumns: "52px 40px 1fr 90px 64px 48px",
                gap: 8,
                padding: "0 10px 6px",
                borderBottom: `1px solid ${BRAND.border}`,
                marginBottom: 6,
              } as React.CSSProperties}>
                {["Time", "Dur", "Client", "Piece", "Artist", ""].map((h, i) => (
                  <span key={i} style={{
                    fontFamily: FONT.sans,
                    fontSize: 9,
                    color: BRAND.stoneLight,
                    fontWeight: 600,
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  } as React.CSSProperties}>{h}</span>
                ))}
              </div>
              {scheduleRows.map((row, i) => (
                <ScheduleRow key={row.t} row={row} first={i === 0} />
              ))}
            </div>

            {/* Project pulse */}
            <div style={{
              background: BRAND.white,
              border: `1px solid ${BRAND.border}`,
              borderRadius: 10,
              padding: "14px",
            } as React.CSSProperties}>
              <DashSectionHeader label="Project pulse" action="All projects" />
              {/* Column headers */}
              <div style={{
                display: "grid",
                gridTemplateColumns: "1fr 80px 80px 64px",
                gap: 8,
                padding: "0 10px 6px",
                borderBottom: `1px solid ${BRAND.border}`,
                marginBottom: 6,
              } as React.CSSProperties}>
                {["Client", "Session", "Deposit", "Progress"].map((h, i) => (
                  <span key={i} style={{
                    fontFamily: FONT.sans,
                    fontSize: 9,
                    color: BRAND.stoneLight,
                    fontWeight: 600,
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  } as React.CSSProperties}>{h}</span>
                ))}
              </div>
              {projectRows.map((row, i) => (
                <ProjectRow key={row.c} row={row} first={i === 0} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

