"use client";

import React from "react";
import {
  Sparkles, Inbox, Calendar, MessageSquare, Clock,
  Users, LayoutGrid, ImageIcon, FileText, CreditCard,
  Package, BarChart3, Settings, ChevronRight,
  AlertTriangle, TrendingUp, Zap,
} from "lucide-react";
import { BRAND, FONT } from "@/lib/brand";

// ─── Types ────────────────────────────────────────────────────────────────────

interface NavGroupProps {
  title: string;
  items: Array<{
    icon: React.ComponentType<{ size?: number; strokeWidth?: number }>;
    label: string;
    active?: boolean;
    badge?: number;
    tag?: string;
  }>;
}

interface ScheduleRowProps {
  row: {
    t: string;
    d: string;
    c: string;
    p: string;
    a: string;
    status?: "live" | "next";
    warn?: boolean;
  };
  first: boolean;
}

interface ProjectRowProps {
  row: {
    c: string;
    s: string;
    dep: string;
    dot: string;
    pct: number;
  };
  first: boolean;
}

interface DashboardMockupProps {
  hero?: boolean;
}

// ─── NavGroup ─────────────────────────────────────────────────────────────────

function NavGroup({ title, items }: NavGroupProps) {
  return (
    <div style={{ marginBottom: 20 } as React.CSSProperties}>
      <div style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        fontWeight: 600,
        color: "#5A5755",
        letterSpacing: "0.08em",
        textTransform: "uppercase",
        padding: "0 12px",
        marginBottom: 4,
      } as React.CSSProperties}>{title}</div>
      {items.map((item) => {
        const Icon = item.icon;
        return (
          <div
            key={item.label}
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "6px 12px",
              borderRadius: 7,
              background: item.active ? "rgba(200,53,31,0.15)" : "transparent",
              marginBottom: 1,
              cursor: "pointer",
            } as React.CSSProperties}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 8 } as React.CSSProperties}>
              <Icon size={13} strokeWidth={1.8} />
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 12,
                fontWeight: item.active ? 500 : 400,
                color: item.active ? BRAND.rustBright : "#9A9792",
                letterSpacing: "-0.01em",
              } as React.CSSProperties}>{item.label}</span>
            </div>
            {item.badge !== undefined && item.badge > 0 && (
              <span style={{
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                minWidth: 16,
                height: 16,
                borderRadius: 100,
                background: BRAND.rust,
                fontFamily: FONT.sans,
                fontSize: 9,
                fontWeight: 600,
                color: BRAND.white,
                padding: "0 4px",
              } as React.CSSProperties}>{item.badge}</span>
            )}
            {item.tag && (
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 9,
                color: BRAND.amber,
                background: "rgba(216,149,56,0.15)",
                padding: "1px 5px",
                borderRadius: 4,
                fontWeight: 500,
              } as React.CSSProperties}>{item.tag}</span>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ─── DashSectionHeader ────────────────────────────────────────────────────────

function DashSectionHeader({ label, action }: { label: string; action?: string }) {
  return (
    <div style={{
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      marginBottom: 10,
    } as React.CSSProperties}>
      <span style={{
        fontFamily: FONT.sans,
        fontSize: 11,
        fontWeight: 600,
        color: BRAND.stoneDark,
        letterSpacing: "0.04em",
        textTransform: "uppercase",
      } as React.CSSProperties}>{label}</span>
      {action && (
        <button style={{
          display: "flex",
          alignItems: "center",
          gap: 2,
          background: "none",
          border: "none",
          cursor: "pointer",
          fontFamily: FONT.sans,
          fontSize: 10,
          color: BRAND.stone,
          padding: 0,
        } as React.CSSProperties}>
          {action}
          <ChevronRight size={10} strokeWidth={2} />
        </button>
      )}
    </div>
  );
}

// ─── ScheduleRow ──────────────────────────────────────────────────────────────

function ScheduleRow({ row }: ScheduleRowProps) {
  return (
    <div style={{
      display: "grid",
      gridTemplateColumns: "52px 40px 1fr 90px 64px 48px",
      alignItems: "center",
      gap: 8,
      padding: "7px 10px",
      borderRadius: 7,
      background: row.status === "live"
        ? "rgba(200,53,31,0.06)"
        : row.status === "next"
        ? "rgba(247,247,245,0.8)"
        : "transparent",
      border: row.status === "live"
        ? `1px solid rgba(200,53,31,0.15)`
        : "1px solid transparent",
      marginBottom: 3,
    } as React.CSSProperties}>
      <span style={{
        fontFamily: FONT.mono,
        fontSize: 10,
        color: row.status === "live" ? BRAND.rust : BRAND.stone,
        fontWeight: row.status === "live" ? 600 : 400,
      } as React.CSSProperties}>{row.t}</span>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 9,
        color: BRAND.stoneLight,
        background: BRAND.boneDeep,
        padding: "2px 5px",
        borderRadius: 4,
        textAlign: "center",
      } as React.CSSProperties}>{row.d}</span>

      <div style={{ display: "flex", alignItems: "center", gap: 6 } as React.CSSProperties}>
        {row.warn && (
          <AlertTriangle
            size={10}
            strokeWidth={2}
            style={{ color: BRAND.amber, flexShrink: 0 } as React.CSSProperties}
          />
        )}
        <span style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          color: BRAND.ink,
          fontWeight: 500,
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
        } as React.CSSProperties}>{row.c}</span>
      </div>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stone,
        whiteSpace: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis",
      } as React.CSSProperties}>{row.p}</span>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stoneDark,
        whiteSpace: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis",
      } as React.CSSProperties}>{row.a}</span>

      <div style={{ display: "flex", justifyContent: "flex-end" } as React.CSSProperties}>
        {row.status === "live" && (
          <span style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 3,
            background: BRAND.rust,
            color: BRAND.white,
            fontFamily: FONT.sans,
            fontSize: 8,
            fontWeight: 600,
            padding: "2px 6px",
            borderRadius: 4,
            letterSpacing: "0.04em",
            textTransform: "uppercase",
          } as React.CSSProperties}>
            <span style={{
              width: 4,
              height: 4,
              borderRadius: 100,
              background: BRAND.white,
              display: "inline-block",
              animation: "inkos-pulse 1.4s ease-in-out infinite",
            } as React.CSSProperties} />
            LIVE
          </span>
        )}
        {row.status === "next" && (
          <span style={{
            fontFamily: FONT.sans,
            fontSize: 8,
            color: BRAND.stoneDark,
            background: BRAND.boneDeep,
            padding: "2px 6px",
            borderRadius: 4,
            letterSpacing: "0.02em",
          } as React.CSSProperties}>NEXT</span>
        )}
      </div>
    </div>
  );
}

// ─── ProjectRow ───────────────────────────────────────────────────────────────

function ProjectRow({ row }: ProjectRowProps) {
  return (
    <div style={{
      display: "grid",
      gridTemplateColumns: "1fr 80px 80px 64px",
      alignItems: "center",
      gap: 8,
      padding: "7px 10px",
      borderRadius: 7,
      marginBottom: 3,
    } as React.CSSProperties}>
      <div style={{ display: "flex", alignItems: "center", gap: 6 } as React.CSSProperties}>
        <span style={{
          width: 7,
          height: 7,
          borderRadius: 100,
          background: row.dot,
          display: "inline-block",
          flexShrink: 0,
        } as React.CSSProperties} />
        <span style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          fontWeight: 500,
          color: BRAND.ink,
        } as React.CSSProperties}>{row.c}</span>
      </div>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stone,
      } as React.CSSProperties}>{row.s}</span>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stoneDark,
        fontWeight: 500,
      } as React.CSSProperties}>{row.dep}</span>

      <div>
        <div style={{
          height: 4,
          borderRadius: 100,
          background: BRAND.boneDeep,
          overflow: "hidden",
        } as React.CSSProperties}>
          <div style={{
            height: "100%",
            width: `${row.pct}%`,
            borderRadius: 100,
            background: row.pct >= 80 ? BRAND.sage : row.pct >= 50 ? BRAND.amber : BRAND.rust,
            transition: "width 0.3s ease",
          } as React.CSSProperties} />
        </div>
        <div style={{
          fontFamily: FONT.mono,
          fontSize: 9,
          color: BRAND.stoneLight,
          marginTop: 2,
          textAlign: "right",
        } as React.CSSProperties}>{row.pct}%</div>
      </div>
    </div>
  );
}

// ─── Data ─────────────────────────────────────────────────────────────────────

const scheduleRows: ScheduleRowProps["row"][] = [
  { t: "10:00", d: "3h",   c: "Asha Mehra",  p: "Sleeve — session 4",   a: "Zara K.", status: "live" },
  { t: "13:30", d: "2h",   c: "Marcus Lane", p: "Geometric chest",      a: "Zara K.", status: "next" },
  { t: "14:00", d: "1.5h", c: "Elena Ruiz",  p: "Watercolour wrist",    a: "Dev P.",  warn: true },
  { t: "16:30", d: "2h",   c: "Jonah Park",  p: "Portrait — session 2", a: "Dev P." },
];

const projectRows: ProjectRowProps["row"][] = [
  { c: "Asha Mehra",  s: "Sess 4 / 6", dep: "£420 held", dot: BRAND.rust,  pct: 65 },
  { c: "Elena Ruiz",  s: "Sess 1 / 3", dep: "£150 held", dot: BRAND.amber, pct: 30 },
  { c: "Tomas Bel.",  s: "Sess 2 / 4", dep: "£300 held", dot: BRAND.sage,  pct: 48 },
];

const kpis: Array<{
  label: string;
  value: string;
  change: string;
  up: boolean;
  icon: React.ComponentType<{ size?: number; strokeWidth?: number }>;
}> = [
  { label: "Today's revenue",    value: "£1,840", change: "+12%", up: true,  icon: TrendingUp },
  { label: "Active projects",    value: "14",     change: "+3",   up: true,  icon: LayoutGrid },
  { label: "Bookings this week", value: "22",     change: "−1",   up: false, icon: Calendar },
  { label: "Open deposits",      value: "£6,320", change: "+8%",  up: true,  icon: CreditCard },
];

// ─── DashboardMockup ──────────────────────────────────────────────────────────

export function DashboardMockup({ hero = false }: DashboardMockupProps) {
  const scale = hero ? 0.72 : 1;

  return (
    <div style={{
      width: "100%",
      transformOrigin: "top center",
      transform: hero ? `scale(${scale})` : "none",
      marginBottom: hero ? `calc((1 - ${scale}) * -300px)` : 0,
    } as React.CSSProperties}>
      {/* Browser chrome */}
      <div style={{
        background: BRAND.boneDeep,
        borderRadius: "14px 14px 0 0",
        padding: "10px 16px",
        display: "flex",
        alignItems: "center",
        gap: 10,
        border: `1px solid ${BRAND.border}`,
        borderBottom: "none",
      } as React.CSSProperties}>
        <div style={{ display: "flex", gap: 6 } as React.CSSProperties}>
          {([BRAND.rust, BRAND.amber, BRAND.sage] as string[]).map((c, i) => (
            <span key={i} style={{
              width: 10, height: 10, borderRadius: 100,
              background: c, display: "inline-block", opacity: 0.7,
            } as React.CSSProperties} />
          ))}
        </div>
        <div style={{
          flex: 1,
          background: BRAND.white,
          border: `1px solid ${BRAND.border}`,
          borderRadius: 6,
          padding: "4px 10px",
          fontFamily: FONT.mono,
          fontSize: 10,
          color: BRAND.stone,
          maxWidth: 320,
          margin: "0 auto",
        } as React.CSSProperties}>
          app.inkos.studio/today
        </div>
        <div style={{ marginLeft: "auto" } as React.CSSProperties}>
          <Zap size={12} strokeWidth={1.8} style={{ color: BRAND.amber, opacity: 0.7 } as React.CSSProperties} />
        </div>
      </div>

      {/* App shell */}
      <div style={{
        display: "grid",
        gridTemplateColumns: "196px 1fr",
        height: 540,
        border: `1px solid ${BRAND.border}`,
        borderRadius: "0 0 14px 14px",
        overflow: "hidden",
        boxShadow: "0 32px 80px -16px rgba(15,15,15,0.18), 0 8px 24px -8px rgba(15,15,15,0.08)",
      } as React.CSSProperties}>

        {/* Sidebar */}
        <div style={{
          background: BRAND.onyx,
          borderRight: "1px solid rgba(255,255,255,0.06)",
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
        } as React.CSSProperties}>
          {/* Sidebar header */}
          <div style={{
            padding: "14px 12px 12px",
            borderBottom: "1px solid rgba(255,255,255,0.06)",
            display: "flex",
            alignItems: "center",
            gap: 8,
          } as React.CSSProperties}>
            <div style={{
              width: 22, height: 22,
              background: BRAND.rust,
              borderRadius: 5,
              display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0,
            } as React.CSSProperties}>
              <span style={{
                fontFamily: FONT.serif,
                fontStyle: "italic",
                fontSize: 12,
                color: BRAND.white,
                lineHeight: 1,
              } as React.CSSProperties}>i</span>
            </div>
            <span style={{
              fontFamily: FONT.sans,
              fontSize: 12,
              fontWeight: 600,
              color: BRAND.bone,
              letterSpacing: "-0.01em",
            } as React.CSSProperties}>InkOS</span>
            <span style={{
              marginLeft: "auto",
              fontFamily: FONT.sans,
              fontSize: 9,
              fontWeight: 600,
              color: BRAND.amber,
              background: "rgba(216,149,56,0.15)",
              padding: "2px 5px",
              borderRadius: 4,
            } as React.CSSProperties}>Pro</span>
          </div>

          {/* Nav groups */}
          <div style={{
            flex: 1,
            overflowY: "auto",
            padding: "12px 8px",
          } as React.CSSProperties}>
            <NavGroup
              title="Today"
              items={[
                { icon: Sparkles,      label: "Today",        active: true },
                { icon: Inbox,         label: "Inbox",        badge: 4 },
                { icon: Calendar,      label: "Calendar" },
                { icon: MessageSquare, label: "Messages",     badge: 2 },
                { icon: Clock,         label: "Appointments" },
              ]}
            />
            <NavGroup
              title="Studio"
              items={[
                { icon: Users,      label: "Clients" },
                { icon: LayoutGrid, label: "Projects",  tag: "14" },
                { icon: ImageIcon,  label: "Portfolio" },
                { icon: FileText,   label: "Forms" },
                { icon: CreditCard, label: "Payments" },
                { icon: Package,    label: "Inventory" },
              ]}
            />
            <NavGroup
              title="Grow"
              items={[
                { icon: BarChart3, label: "Analytics" },
                { icon: Sparkles,  label: "AI Studio", tag: "NEW" },
              ]}
            />
          </div>

          {/* User row */}
          <div style={{
            padding: "10px 12px",
            borderTop: "1px solid rgba(255,255,255,0.06)",
            display: "flex",
            alignItems: "center",
            gap: 8,
          } as React.CSSProperties}>
            <div style={{
              width: 26, height: 26,
              borderRadius: 100,
              background: "linear-gradient(135deg, #C8351F 0%, #D89538 100%)",
              display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0,
            } as React.CSSProperties}>
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 10,
                fontWeight: 600,
                color: BRAND.white,
              } as React.CSSProperties}>ZK</span>
            </div>
            <div style={{ flex: 1, minWidth: 0 } as React.CSSProperties}>
              <div style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                fontWeight: 500,
                color: BRAND.bone,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              } as React.CSSProperties}>Zara Kowalski</div>
              <div style={{
                fontFamily: FONT.sans,
                fontSize: 9,
                color: "#5A5755",
              } as React.CSSProperties}>Lead artist</div>
            </div>
            <Settings
              size={12}
              strokeWidth={1.8}
              style={{ color: "#5A5755", flexShrink: 0 } as React.CSSProperties}
            />
          </div>
        </div>

        {/* Main area */}
        <div style={{
          background: BRAND.bone,
          overflowY: "auto",
          padding: "18px 20px",
          display: "flex",
          flexDirection: "column",
          gap: 18,
        } as React.CSSProperties}>

          {/* Page header */}
          <div style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          } as React.CSSProperties}>
            <div>
              <div style={{
                fontFamily: FONT.serif,
                fontSize: 20,
                color: BRAND.ink,
                lineHeight: 1.2,
              } as React.CSSProperties}>Good morning, Zara</div>
              <div style={{
                fontFamily: FONT.sans,
                fontSize: 12,
                color: BRAND.stone,
                marginTop: 2,
              } as React.CSSProperties}>Monday, 27 April — 4 appointments today</div>
            </div>
            <button style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "7px 14px",
              borderRadius: 8,
              background: BRAND.onyx,
              border: "none",
              cursor: "pointer",
              fontFamily: FONT.sans,
              fontSize: 11,
              fontWeight: 500,
              color: BRAND.bone,
            } as React.CSSProperties}>
              <Clock size={11} strokeWidth={2} />
              New booking
            </button>
          </div>

          {/* KPI grid */}
          <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: 10,
          } as React.CSSProperties}>
            {kpis.map((kpi) => {
              const Icon = kpi.icon;
              return (
                <div key={kpi.label} style={{
                  background: BRAND.white,
                  border: `1px solid ${BRAND.border}`,
                  borderRadius: 10,
                  padding: "12px 14px",
                } as React.CSSProperties}>
                  <div style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    marginBottom: 8,
                  } as React.CSSProperties}>
                    <span style={{
                      fontFamily: FONT.sans,
                      fontSize: 10,
                      color: BRAND.stone,
                    } as React.CSSProperties}>{kpi.label}</span>
                    <Icon size={12} strokeWidth={1.8} />
                  </div>
                  <div style={{
                    fontFamily: FONT.sans,
                    fontSize: 20,
                    fontWeight: 600,
                    color: BRAND.ink,
                    letterSpacing: "-0.02em",
                    lineHeight: 1,
                    marginBottom: 4,
                  } as React.CSSProperties}>{kpi.value}</div>
                  <div style={{
                    fontFamily: FONT.sans,
                    fontSize: 10,
                    color: kpi.up ? BRAND.sage : BRAND.rust,
                    fontWeight: 500,
                  } as React.CSSProperties}>{kpi.change} vs last week</div>
                </div>
              );
            })}
          </div>

          {/* Allergy alert */}
          <div style={{
            background: BRAND.amberWash,
            border: `1px solid ${BRAND.amberSoft}`,
            borderRadius: 10,
            padding: "10px 14px",
            display: "flex",
            alignItems: "flex-start",
            gap: 10,
          } as React.CSSProperties}>
            <AlertTriangle
              size={14}
              strokeWidth={2}
              style={{ color: BRAND.amber, flexShrink: 0, marginTop: 1 } as React.CSSProperties}
            />
            <div>
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                fontWeight: 600,
                color: BRAND.ink,
              } as React.CSSProperties}>Allergy alert — Elena Ruiz </span>
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                color: BRAND.stoneDark,
              } as React.CSSProperties}>
                Known sensitivity to red ink (Eternal Ink Crimson Red). Patch tested 2024-11. Use black or sage alternatives for fill.
              </span>
            </div>
          </div>

          {/* Bottom grid: schedule + project pulse */}
          <div style={{
            display: "grid",
            gridTemplateColumns: "1fr 280px",
            gap: 14,
            flex: 1,
            minHeight: 0,
          } as React.CSSProperties}>

            {/* Schedule */}
            <div style={{
              background: BRAND.white,
              border: `1px solid ${BRAND.border}`,
              borderRadius: 10,
              padding: "14px",
              overflow: "hidden",
            } as React.CSSProperties}>
              <DashSectionHeader label="Today's schedule" action="View full calendar" />
              <div style={{
                display: "grid",
                gridTemplateColumns: "52px 40px 1fr 90px 64px 48px",
                gap: 8,
                padding: "0 10px 6px",
                borderBottom: `1px solid ${BRAND.border}`,
                marginBottom: 6,
              } as React.CSSProperties}>
                {["Time", "Dur", "Client", "Piece", "Artist", ""].map((h, i) => (
                  <span key={i} style={{
                    fontFamily: FONT.sans,
                    fontSize: 9,
                    color: BRAND.stoneLight,
                    fontWeight: 600,
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  } as React.CSSProperties}>{h}</span>
                ))}
              </div>
              {scheduleRows.map((row, i) => (
                <ScheduleRow key={row.t} row={row} first={i === 0} />
              ))}
            </div>

            {/* Project pulse */}
            <div style={{
              background: BRAND.white,
              border: `1px solid ${BRAND.border}`,
              borderRadius: 10,
              padding: "14px",
              overflow: "hidden",
            } as React.CSSProperties}>
              <DashSectionHeader label="Project pulse" action="All projects" />
              <div style={{
                display: "grid",
                gridTemplateColumns: "1fr 80px 80px 64px",
                gap: 8,
                padding: "0 10px 6px",
                borderBottom: `1px solid ${BRAND.border}`,
                marginBottom: 6,
              } as React.CSSProperties}>
                {["Client", "Session", "Deposit", "Progress"].map((h, i) => (
                  <span key={i} style={{
                    fontFamily: FONT.sans,
                    fontSize: 9,
                    color: BRAND.stoneLight,
                    fontWeight: 600,
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  } as React.CSSProperties}>{h}</span>
                ))}
              </div>
              {projectRows.map((row, i) => (
                <ProjectRow key={row.c} row={row} first={i === 0} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

